param([string]$HostIP='127.0.0.1',[int]$Port=8765)
$ErrorActionPreference='Stop'
$Root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$Uploads=Join-Path $PSScriptRoot 'uploads'; New-Item -ItemType Directory -Force -Path $Uploads|Out-Null
$DbName='mes_lion'; $DbUser='postgres'; $DbHost='localhost'; $DbPort='5432'
function Find-Psql { $c=Get-Command psql.exe -ErrorAction SilentlyContinue;if($c){return $c.Source};$xs=Get-ChildItem 'C:\Program Files\PostgreSQL' -Filter psql.exe -Recurse -ErrorAction SilentlyContinue|Sort-Object FullName -Descending;if($xs){return $xs[0].FullName};throw 'psql.exe não encontrado. O PostgreSQL precisa estar instalado.' }
$Psql=Find-Psql
$sec=Read-Host 'Senha do usuario postgres (nao sera salva)' -AsSecureString
$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec);try{$env:PGPASSWORD=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)}
function Sql([string]$q){$tmp=Join-Path $env:TEMP ('mes_sql_'+[guid]::NewGuid().ToString('N')+'.sql');try{[IO.File]::WriteAllText($tmp,$q,(New-Object Text.UTF8Encoding($false)));$o=& $Psql -h $DbHost -p $DbPort -U $DbUser -d $DbName -X -q -t -A -v ON_ERROR_STOP=1 -f $tmp 2>&1;if($LASTEXITCODE -ne 0){throw ($o -join "`n")};return ($o -join "`n").Trim()}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}}
function Lit([string]$s){if($null -eq $s){return 'NULL'};return "'"+($s -replace "'","''")+"'"}
function JsonLit([string]$s){return (Lit $s)+"::jsonb"}
function B64Lit([string]$s){if($null -eq $s){return 'NULL'};$b=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($s));return "convert_from(decode('$b','base64'),'UTF8')"}
# Ensure schema and seed admin/state.
& $Psql -h $DbHost -p $DbPort -U $DbUser -d $DbName -X -q -v ON_ERROR_STOP=1 -f (Join-Path $Root 'database\schema.sql') | Out-Null
if([int](Sql 'SELECT count(*) FROM users') -eq 0){Sql "INSERT INTO users(username,full_name,password_hash,role) VALUES('admin','Administrador MES LION',crypt('meslion2026',gen_salt('bf')),'ADMIN')"|Out-Null}
if([int](Sql 'SELECT count(*) FROM app_state') -eq 0){$seed=Get-Content (Join-Path $Root 'Dados\MES_LION_DATA.json') -Raw -Encoding UTF8;$tmp=Join-Path $env:TEMP ('mes_seed_'+[guid]::NewGuid()+'.sql');("INSERT INTO app_state(id,payload) VALUES(1,"+(JsonLit $seed)+");")|Set-Content $tmp -Encoding UTF8;& $Psql -h $DbHost -p $DbPort -U $DbUser -d $DbName -X -q -v ON_ERROR_STOP=1 -f $tmp|Out-Null;Remove-Item $tmp -Force}
$Sessions=@{}
function UserFromHeaders($h){if(!$h.ContainsKey('cookie')){return $null};$m=[regex]::Match($h['cookie'],'MESSESSION=([^;]+)');if(!$m.Success){return $null};$t=$m.Groups[1].Value;if($Sessions.ContainsKey($t)){return $Sessions[$t]};return $null}
function Mime($p){switch([IO.Path]::GetExtension($p).ToLower()){'.html'{'text/html; charset=utf-8'}'.js'{'application/javascript; charset=utf-8'}'.css'{'text/css; charset=utf-8'}'.jpg'{'image/jpeg'}'.jpeg'{'image/jpeg'}'.png'{'image/png'}'.pdf'{'application/pdf'}'.xlsx'{'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}'.xls'{'application/vnd.ms-excel'}default{'application/octet-stream'}}}
function Resp($stream,[int]$code,[byte[]]$body,[string]$type='application/json; charset=utf-8',[hashtable]$extra=$null){$reason=@{200='OK';201='Created';204='No Content';400='Bad Request';401='Unauthorized';403='Forbidden';404='Not Found';500='Internal Server Error'}[$code];if(!$reason){$reason='OK'};$head="HTTP/1.1 $code $reason`r`nContent-Type: $type`r`nContent-Length: $($body.Length)`r`nConnection: close`r`nCache-Control: no-store`r`n";if($extra){foreach($k in $extra.Keys){$head+="$k`: $($extra[$k])`r`n"}};$head+="`r`n";$hb=[Text.Encoding]::ASCII.GetBytes($head);$stream.Write($hb,0,$hb.Length);if($body.Length){$stream.Write($body,0,$body.Length)}}
function JResp($s,$code,$obj,$extra=$null){$json=$obj|ConvertTo-Json -Depth 100 -Compress;Resp $s $code ([Text.Encoding]::UTF8.GetBytes($json)) 'application/json; charset=utf-8' $extra}
function TResp($s,$code,[string]$txt,$type='text/plain; charset=utf-8',$extra=$null){Resp $s $code ([Text.Encoding]::UTF8.GetBytes($txt)) $type $extra}
function Audit($u,$module,$action,$key='',$details='{}'){if(!$u){return};Sql "INSERT INTO audit_log(user_id,username,module,action,record_key,details) VALUES($(Lit $u.id),$(Lit $u.username),$(Lit $module),$(Lit $action),$(Lit $key),$(JsonLit $details))"|Out-Null}
function ReadRequest($client){$st=$client.GetStream();$buf=New-Object byte[] 8192;$mem=New-Object IO.MemoryStream;$headerEnd=-1;while($headerEnd -lt 0){$n=$st.Read($buf,0,$buf.Length);if($n -le 0){break};$mem.Write($buf,0,$n);$a=$mem.ToArray();for($i=[Math]::Max(0,$a.Length-$n-4);$i -le $a.Length-4;$i++){if($a[$i]-eq 13 -and $a[$i+1]-eq 10 -and $a[$i+2]-eq 13 -and $a[$i+3]-eq 10){$headerEnd=$i+4;break}}};$all=$mem.ToArray();if($headerEnd -lt 0){return $null};$hs=[Text.Encoding]::ASCII.GetString($all,0,$headerEnd);$lines=$hs -split "`r`n";$first=$lines[0] -split ' ';$headers=@{};for($i=1;$i -lt $lines.Count;$i++){if($lines[$i] -match '^([^:]+):\s*(.*)$'){$headers[$matches[1].ToLower()]=$matches[2]}};$len=0;if($headers.ContainsKey('content-length')){$len=[int]$headers['content-length']};$body=New-Object byte[] $len;$have=$all.Length-$headerEnd;if($have -gt 0){[Array]::Copy($all,$headerEnd,$body,0,[Math]::Min($have,$len))};$pos=[Math]::Min($have,$len);while($pos -lt $len){$n=$st.Read($body,$pos,$len-$pos);if($n -le 0){break};$pos+=$n};return @{stream=$st;method=$first[0];path=$first[1];headers=$headers;body=$body}}
function ParseMultipart($req){$ct=$req.headers['content-type'];$bm=[regex]::Match($ct,'boundary=(.+)$');if(!$bm.Success){return @{}};$b='--'+$bm.Groups[1].Value.Trim('"');$enc=[Text.Encoding]::GetEncoding(28591);$txt=$enc.GetString($req.body);$out=@{};foreach($part in ($txt -split [regex]::Escape($b))){if($part -notmatch 'Content-Disposition: form-data; name="([^"]+)"'){continue};$name=$matches[1];$idx=$part.IndexOf("`r`n`r`n");if($idx -lt 0){continue};$content=$part.Substring($idx+4).TrimEnd("`r","`n","-");if($part -match 'filename="([^"]*)"'){$out[$name]=@{filename=$matches[1];bytes=$enc.GetBytes($content)}}else{$out[$name]=$content}};return $out}
if($HostIP -eq '0.0.0.0' -or $HostIP -eq '*'){ $BindAddress=[Net.IPAddress]::Any } else { $BindAddress=[Net.IPAddress]::Parse($HostIP) }
try {
  $listener=[Net.Sockets.TcpListener]::new($BindAddress,$Port)
  $listener.Start()
} catch {
  Write-Host ''
  Write-Host "ERRO: nao foi possivel abrir a porta $Port." -ForegroundColor Red
  Write-Host 'Feche qualquer versao anterior do MES e tente novamente.' -ForegroundColor Yellow
  Write-Host $_.Exception.Message -ForegroundColor Red
  exit 2
}
$bound=$listener.LocalEndpoint.Address.ToString()
Write-Host ''
Write-Host 'MES LION V2.3.6 - PostgreSQL / PowerShell' -ForegroundColor Green
Write-Host "Escutando em: $bound`:$Port" -ForegroundColor Cyan
if($BindAddress.Equals([Net.IPAddress]::Any)){
  Write-Host 'MODO REDE ATIVO: conexoes IPv4 de outros computadores estao habilitadas.' -ForegroundColor Green
  Write-Host "Acesse neste PC por http://localhost:$Port e, nos demais PCs, use http://IP-DESTE-PC:$Port"
} else {
  Write-Host "MODO LOCAL: http://localhost:$Port"
}
Write-Host 'Usuario inicial: admin  |  Senha inicial: meslion2026'
Write-Host 'Mantenha esta janela aberta. Ctrl+C encerra.'
if($BindAddress.Equals([Net.IPAddress]::Loopback)){Start-Process "http://localhost:$Port"}
while($true){$c=$listener.AcceptTcpClient();try{$r=ReadRequest $c;if(!$r){continue};$s=$r.stream;$method=$r.method;$raw=$r.path;$path=([uri]('http://x'+$raw)).AbsolutePath;$u=UserFromHeaders $r.headers
try{
 if($path -eq '/api/auth/login' -and $method -eq 'POST'){$b=[Text.Encoding]::UTF8.GetString($r.body)|ConvertFrom-Json;$q=Sql "SELECT row_to_json(x)::text FROM (SELECT id::text,username,full_name,role FROM users WHERE username=$(Lit $b.username) AND active=true AND password_hash=crypt($(Lit $b.password),password_hash) LIMIT 1)x";if(!$q){JResp $s 401 @{error='Usuário ou senha inválidos'};continue};$usr=$q|ConvertFrom-Json;$tok=[guid]::NewGuid().ToString('N');$Sessions[$tok]=@{id=$usr.id;username=$usr.username;fullName=$usr.full_name;role=$usr.role};Audit $Sessions[$tok] 'auth' 'LOGIN' $usr.username;JResp $s 200 @{user=$Sessions[$tok]} @{'Set-Cookie'="MESSESSION=$tok; Path=/; HttpOnly; SameSite=Lax"};continue}
 if($path -eq '/api/auth/logout' -and $method -eq 'POST'){JResp $s 200 @{ok=$true} @{'Set-Cookie'='MESSESSION=; Path=/; Max-Age=0'};continue}
 if($path -eq '/api/auth/me') {if(!$u){JResp $s 401 @{error='Não autenticado'}}else{JResp $s 200 @{user=$u}};continue}
 if($path.StartsWith('/api/') -and !$u){JResp $s 401 @{error='Não autenticado'};continue}
 if($path -eq '/api/bootstrap'){$d=Sql "SELECT payload::text FROM app_state WHERE id=1";$kv=Sql "SELECT coalesce(json_object_agg(key,value),'{}'::json)::text FROM app_storage";JResp $s 200 @{data=($d|ConvertFrom-Json);appStorage=($kv|ConvertFrom-Json);user=$u};continue}
 if($path -eq '/api/storage' -and $method -eq 'GET'){$kv=Sql "SELECT coalesce(json_object_agg(key,value),'{}'::json)::text FROM app_storage";$o=$kv|ConvertFrom-Json;$d=Sql 'SELECT payload::text FROM app_state WHERE id=1';$o|Add-Member -NotePropertyName MES_LION_DATA -NotePropertyValue $d -Force;JResp $s 200 $o;continue}
 if($path -match '^/api/storage/(.+)$' -and $method -eq 'PUT'){$key=[uri]::UnescapeDataString($matches[1]);$txt=[Text.Encoding]::UTF8.GetString($r.body);if($key -eq 'MES_LION_DATA'){$tmp=Join-Path $env:TEMP ('mes_save_'+[guid]::NewGuid()+'.sql');("UPDATE app_state SET payload="+(JsonLit $txt)+",updated_at=now(),updated_by="+(Lit $u.id)+" WHERE id=1;")|Set-Content $tmp -Encoding UTF8;& $Psql -h $DbHost -p $DbPort -U $DbUser -d $DbName -X -q -v ON_ERROR_STOP=1 -f $tmp|Out-Null;Remove-Item $tmp -Force;Audit $u 'app' 'SAVE_STATE' 'MES_LION_DATA';TResp $s 200 'OK'}else{Sql "INSERT INTO app_storage(key,value) VALUES($(Lit $key),$(Lit $txt)) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=now()"|Out-Null;TResp $s 200 'OK'};continue}
 if($path -eq '/api/users' -and $method -eq 'GET'){if($u.role -ne 'ADMIN'){JResp $s 403 @{error='Acesso administrativo necessário'};continue};$q=Sql "SELECT coalesce(json_agg(x),'[]'::json)::text FROM (SELECT id::text,username,full_name,role,active,created_at,updated_at FROM users ORDER BY full_name)x";TResp $s 200 $q 'application/json; charset=utf-8';continue}
 if($path -eq '/api/users' -and $method -eq 'POST'){if($u.role -ne 'ADMIN'){JResp $s 403 @{error='Acesso administrativo necessário'};continue};$b=[Text.Encoding]::UTF8.GetString($r.body)|ConvertFrom-Json;if([string]::IsNullOrWhiteSpace([string]$b.username) -or [string]::IsNullOrWhiteSpace([string]$b.fullName) -or [string]::IsNullOrWhiteSpace([string]$b.password)){JResp $s 400 @{error='Usuário, nome e senha são obrigatórios'};continue};$active=if($b.active){'TRUE'}else{'FALSE'};$id=Sql "INSERT INTO users(username,full_name,password_hash,role,active) VALUES($(B64Lit ([string]$b.username)),$(B64Lit ([string]$b.fullName)),crypt($(B64Lit ([string]$b.password)),gen_salt('bf')),$(B64Lit ([string]$b.role)),$active) RETURNING id::text";Audit $u 'usuarios' 'CREATE' ([string]$b.username);JResp $s 200 @{id=$id};continue}
 if($path -match '^/api/users/([0-9a-fA-F-]+)$' -and $method -eq 'PUT'){if($u.role -ne 'ADMIN'){JResp $s 403 @{error='Acesso administrativo necessário'};continue};$id=$matches[1];$b=[Text.Encoding]::UTF8.GetString($r.body)|ConvertFrom-Json;$active=if($b.active){'TRUE'}else{'FALSE'};$pw=if(-not [string]::IsNullOrWhiteSpace([string]$b.password)){",password_hash=crypt($(B64Lit ([string]$b.password)),gen_salt('bf'))"}else{''};Sql "UPDATE users SET full_name=$(B64Lit ([string]$b.fullName)),role=$(B64Lit ([string]$b.role)),active=$active,updated_at=now()$pw WHERE id=$(Lit $id)"|Out-Null;Audit $u 'usuarios' 'UPDATE' $id;JResp $s 200 @{ok=$true};continue}
 if($path -eq '/api/audit'){$q=Sql "SELECT coalesce(json_agg(x),'[]'::json)::text FROM (SELECT username,module,action,record_key,changed_at,details FROM audit_log ORDER BY changed_at DESC LIMIT 500)x";TResp $s 200 $q 'application/json; charset=utf-8';continue}
 if($path -match '^/api/equipment/(.+)/documents$' -and $method -eq 'GET'){$code=[uri]::UnescapeDataString($matches[1]);$q=Sql "SELECT coalesce(json_agg(x),'[]'::json)::text FROM (SELECT id::text,equipment_code,original_name,mime_type,file_size,document_type,revision,active,uploaded_at FROM equipment_documents WHERE equipment_code=$(Lit $code) AND active=true ORDER BY uploaded_at DESC)x";TResp $s 200 $q 'application/json; charset=utf-8';continue}
 if($path -match '^/api/equipment/(.+)/documents$' -and $method -eq 'POST'){$code=[uri]::UnescapeDataString($matches[1]);$m=ParseMultipart $r;if(!$m.file){JResp $s 400 @{error='Arquivo obrigatório'};continue};$ext=[IO.Path]::GetExtension($m.file.filename).ToLower();if(@('.pdf','.xlsx','.xls') -notcontains $ext){JResp $s 400 @{error='Somente PDF/XLS/XLSX'};continue};$stored=([guid]::NewGuid().ToString()+$ext);[IO.File]::WriteAllBytes((Join-Path $Uploads $stored),$m.file.bytes);$mime=Mime $m.file.filename;$size=$m.file.bytes.Length;$id=Sql "INSERT INTO equipment_documents(equipment_code,original_name,stored_name,mime_type,file_size,document_type,revision,uploaded_by) VALUES($(Lit $code),$(Lit $m.file.filename),$(Lit $stored),$(Lit $mime),$size,$(Lit ([string]$m.documentType)),$(Lit ([string]$m.revision)),$(Lit $u.id)) RETURNING id::text";Audit $u 'equipamentos' 'UPLOAD_DOCUMENT' $code;JResp $s 200 @{id=$id};continue}
 if($path -match '^/api/documents/([0-9a-fA-F-]+)$'){$id=$matches[1];$q=Sql "SELECT row_to_json(x)::text FROM (SELECT original_name,stored_name,mime_type FROM equipment_documents WHERE id=$(Lit $id) AND active=true)x";if(!$q){TResp $s 404 'Não encontrado';continue};$d=$q|ConvertFrom-Json;$fp=Join-Path $Uploads $d.stored_name;if(!(Test-Path $fp)){TResp $s 404 'Arquivo não encontrado';continue};Resp $s 200 ([IO.File]::ReadAllBytes($fp)) $d.mime_type @{'Content-Disposition'="inline; filename=`"$($d.original_name)`""};continue}
 if($path.StartsWith('/api/')){TResp $s 404 'API não encontrada';continue}
 $rel=if($path -eq '/'){'index.html'}else{$path.TrimStart('/')};$fp=[IO.Path]::GetFullPath((Join-Path $Root $rel));if(!$fp.StartsWith($Root) -or !(Test-Path $fp) -or (Get-Item $fp).PSIsContainer){TResp $s 404 'Não encontrado';continue};Resp $s 200 ([IO.File]::ReadAllBytes($fp)) (Mime $fp)
 }catch{JResp $s 500 @{error=$_.Exception.Message}}
 }finally{$c.Close()}}
